#include <Arduino.h>
const uint8_t CW=5,CCW=6,EA=2,EB=3; volatile long pos=0;
float kp=1,ki=0,kd=0,sp=0,integ=0,prevE=0,alpha=0.3,lpf=0; uint16_t Ts=50; bool positionMode=false,runFlag=false; long prevPos=0; uint32_t last=0;
void encISR(){pos+=(digitalRead(EA)==digitalRead(EB))?1:-1;}
void drive(float u){int p=constrain((int)lround(u),-255,255);analogWrite(CW,p>0?p:0);analogWrite(CCW,p<0?-p:0);}
void parse(String s){s.trim(); if(s=="START")runFlag=true; else if(s=="STOP"){runFlag=false;drive(0);} else if(s=="ZERO"){noInterrupts();pos=0;interrupts();} else {int q=s.indexOf('=');if(q<0)return;String k=s.substring(0,q);float v=s.substring(q+1).toFloat();if(k=="SP")sp=v;else if(k=="KP")kp=v;else if(k=="KI")ki=v;else if(k=="KD")kd=v;else if(k=="ALPHA")alpha=constrain(v,0,1);else if(k=="TS")Ts=constrain((int)v,10,300);else if(k=="MODE"){positionMode=((int)v)==1;if(positionMode){noInterrupts();pos=0;interrupts();}}}}
void setup(){Serial.begin(115200);pinMode(CW,OUTPUT);pinMode(CCW,OUTPUT);pinMode(EA,INPUT_PULLUP);pinMode(EB,INPUT_PULLUP);attachInterrupt(digitalPinToInterrupt(EA),encISR,CHANGE);attachInterrupt(digitalPinToInterrupt(EB),encISR,CHANGE);}
void loop(){if(Serial.available())parse(Serial.readStringUntil('\n')); if(millis()-last<Ts)return;uint32_t now=millis();float dt=(now-last)/1000.0f;last=now;long p;noInterrupts();p=pos;interrupts();float raw=(p-prevPos)/dt;prevPos=p;lpf=alpha*raw+(1-alpha)*lpf;float fb=positionMode?(float)p:lpf;float e=sp-fb;if(ki==0)integ=0;else integ+=e*dt;float P=kp==0?0:kp*e,I=ki==0?0:ki*integ,D=kd==0?0:kd*(e-prevE)/dt;float u=P+I+D;if(u>255){u=255;if(e*ki>0)integ-=e*dt;}if(u<-255){u=-255;if(e*ki<0)integ-=e*dt;}prevE=e;if(runFlag)drive(u);else drive(0);Serial.print(now);Serial.print(',');Serial.print(sp);Serial.print(',');Serial.print(p);Serial.print(',');Serial.print(raw);Serial.print(',');Serial.print(lpf);Serial.print(',');Serial.print(e);Serial.print(',');Serial.print(P);Serial.print(',');Serial.print(I);Serial.print(',');Serial.print(D);Serial.print(',');Serial.println(u);}
